import hashlib, os
from cryptography.hazmat.primitives.asymmetric import ec, mlkem, x25519
from cryptography.hazmat.primitives import serialization

# ---- one interface, several algorithms: callers only see generate / encaps / decaps and a name ----
class KEM:
    name = "abstract"
    def generate(self): raise NotImplementedError          # -> (public key bytes, secret key object)
    def encaps(self, pk): raise NotImplementedError        # -> (ciphertext, shared secret)
    def decaps(self, sk, ct): raise NotImplementedError    # -> shared secret

def _kdf(*parts):
    h = hashlib.sha3_256()
    for p in parts: h.update(len(p).to_bytes(4, "big") + p)
    return h.digest()

class X25519KEM(KEM):
    name = "X25519"
    def generate(self):
        sk = x25519.X25519PrivateKey.generate()
        return sk.public_key().public_bytes_raw(), sk
    def encaps(self, pk):
        eph = x25519.X25519PrivateKey.generate()
        ss = eph.exchange(x25519.X25519PublicKey.from_public_bytes(pk)); ct = eph.public_key().public_bytes_raw()
        return ct, _kdf(b"x25519", ss, ct, pk)
    def decaps(self, sk, ct):
        ss = sk.exchange(x25519.X25519PublicKey.from_public_bytes(ct))
        return _kdf(b"x25519", ss, ct, sk.public_key().public_bytes_raw())

class P256KEM(KEM):
    name = "ECDH-P256"
    def generate(self):
        sk = ec.generate_private_key(ec.SECP256R1())
        return sk.public_key().public_bytes(serialization.Encoding.X962, serialization.PublicFormat.UncompressedPoint), sk
    def encaps(self, pk):
        eph = ec.generate_private_key(ec.SECP256R1())
        peer = ec.EllipticCurvePublicKey.from_encoded_point(ec.SECP256R1(), pk)
        ct = eph.public_key().public_bytes(serialization.Encoding.X962, serialization.PublicFormat.UncompressedPoint)
        return ct, _kdf(b"p256", eph.exchange(ec.ECDH(), peer), ct, pk)
    def decaps(self, sk, ct):
        peer = ec.EllipticCurvePublicKey.from_encoded_point(ec.SECP256R1(), ct)
        pk = sk.public_key().public_bytes(serialization.Encoding.X962, serialization.PublicFormat.UncompressedPoint)
        return _kdf(b"p256", sk.exchange(ec.ECDH(), peer), ct, pk)

class MLKEM768KEM(KEM):
    name = "ML-KEM-768"
    def generate(self):
        sk = mlkem.MLKEM768PrivateKey.generate()
        return sk.public_key().public_bytes_raw(), sk
    def encaps(self, pk):
        ss, ct = mlkem.MLKEM768PublicKey.from_public_bytes(pk).encapsulate()
        return ct, ss
    def decaps(self, sk, ct):
        return sk.decapsulate(ct)

class HybridKEM(KEM):
    """classical + post-quantum: the secret is safe if EITHER component holds (illustrative combiner; deployed hybrids follow the IETF specifications)"""
    def __init__(self, a, b):
        self.a, self.b = a, b
        self.name = f"{a.name}+{b.name}"
    def generate(self):
        pa, sa = self.a.generate(); pb, sb = self.b.generate()
        return len(pa).to_bytes(4, "big") + pa + pb, (sa, sb, len(pa))
    def encaps(self, pk):
        n = int.from_bytes(pk[:4], "big"); pa, pb = pk[4:4 + n], pk[4 + n:]
        ca, ssa = self.a.encaps(pa); cb, ssb = self.b.encaps(pb)
        return len(ca).to_bytes(4, "big") + ca + cb, _kdf(b"hybrid", ssa, ssb, ca, cb)
    def decaps(self, sk, ct):
        sa, sb, _ = sk
        n = int.from_bytes(ct[:4], "big"); ca, cb = ct[4:4 + n], ct[4 + n:]
        return _kdf(b"hybrid", self.a.decaps(sa, ca), self.b.decaps(sb, cb), ca, cb)

REGISTRY = {k.name: k for k in (X25519KEM(), P256KEM(), MLKEM768KEM(), HybridKEM(X25519KEM(), MLKEM768KEM()))}
import socket, threading
from cryptography.hazmat.primitives.ciphers.aead import AESGCM
# Phase 6, Prototype: a tiny client/server exchange over loopback TCP using the KEM layer, to find integration problems early (message sizes, framing, failure behaviour).
def send_msg(sock, data): sock.sendall(len(data).to_bytes(4, "big") + data)
def recv_exact(sock, n):
    buf = b""
    while len(buf) < n:
        chunk = sock.recv(n - len(buf))
        if not chunk: raise ConnectionError("peer closed")
        buf += chunk
    return buf
def recv_msg(sock): return recv_exact(sock, int.from_bytes(recv_exact(sock, 4), "big"))
def run(alg_name):
    kem = REGISTRY[alg_name]
    srv = socket.socket(); srv.bind(("127.0.0.1", 0)); srv.listen(1); port = srv.getsockname()[1]
    result = {}
    def server():
        c, _ = srv.accept()
        pk, sk = kem.generate()
        send_msg(c, pk)                                   # server flight: public key
        ct = recv_msg(c)                                  # client flight: ciphertext
        key = kem.decaps(sk, ct)
        nonce = recv_exact(c, 12); body = recv_msg(c)
        result["server_got"] = AESGCM(key).decrypt(nonce, body, b"proto-v1")
        c.close()
    t = threading.Thread(target=server); t.start()
    cl = socket.create_connection(("127.0.0.1", port), timeout=5)
    pk = recv_msg(cl)
    ct, key = kem.encaps(pk)
    send_msg(cl, ct)
    nonce = os.urandom(12)
    cl.sendall(nonce); send_msg(cl, AESGCM(key).encrypt(nonce, b"hello from the prototype", b"proto-v1"))
    cl.close(); t.join(); srv.close()
    return len(pk), len(ct), result.get("server_got")
MSS = 1460          # typical TCP payload per segment on Ethernet (assumption stated in the output)
print(f"{'algorithm':<22} {'server flight (B)':>17} {'client flight (B)':>17} {'segments (MSS 1460)':>20}  application data arrived")
for name in ("X25519", "ECDH-P256", "ML-KEM-768", "X25519+ML-KEM-768"):
    a, b, got = run(name)
    segs = lambda n: -(-(n + 4) // MSS)
    print(f"{name:<22} {a:>17} {b:>17} {segs(a) + segs(b):>20}  {got!r}")
print()
print("findings from the prototype that would be invisible on paper:")
print("  1. each post-quantum flight is about 1.2 KB: one segment here, but with little margin. A server flight that also carries a certificate chain would span several segments:", -(-(1220 + 4 + 5500) // MSS), "segments with an ML-DSA-65 certificate of about 5.5 KB (E4.5); devices or middleboxes with small buffers or fragment-intolerant paths must be tested")
print("  2. any protocol field sized for 32 or 65 bytes breaks silently or truncates: the framing here uses a 4-byte length for that reason")
print("  3. both ends must agree on the algorithm BEFORE the exchange: the prototype takes it from configuration on both sides; a real protocol negotiates it (E4.6)")
try:
    a, b, got = run("ML-KEM-768")
    k = REGISTRY["ML-KEM-768"]; pk, sk = k.generate(); ct, _ = k.encaps(pk); bad = bytearray(ct); bad[0] ^= 1
